// Renderizar la cuadrícula de productos con filtrado
function renderProducts() {
  const container = document.getElementById('products-grid');
  if (!container) return;

let currentProducts = STOCK_PRODUCTS;
if (AppState.currentMode === 'preorder') currentProducts = PREORDER_PRODUCTS;
if (AppState.currentMode === 'preorder-sports') currentProducts = SPORTS_PRODUCTS;

const isSearching = AppState.searchQuery && AppState.searchQuery.trim().length > 0;
if (isSearching) {
  // Buscador universal que combina todos los catálogos
  currentProducts = [...STOCK_PRODUCTS, ...PREORDER_PRODUCTS, ...SPORTS_PRODUCTS];
}


  const filtered = currentProducts.filter(prod => {
    const isSearching = AppState.searchQuery.trim().length > 0;
    // Si NO está buscando, ocultar productos individuales en la vista principal 'all'
    if (!isSearching && AppState.currentFilter === 'all' && !prod.isFolder && !prod.category.endsWith('_folder')) return false;
    
    // Si ESTÁ buscando, ignoramos el filtro de categoría para buscar en TODO el catálogo
    const matchesCategory = isSearching || AppState.currentFilter === 'all' || 
                            prod.category === AppState.currentFilter || 
                            prod.brand === AppState.currentFilter;
                            
    // Validar nombre
    const matchesSearch = prod.name.toLowerCase().includes(AppState.searchQuery.toLowerCase());
    
    return matchesCategory && matchesSearch;
  });


  if (filtered.length === 0) {
    container.innerHTML = `
      <div style="grid-column: 1 / -1; text-align: center; padding: 40px 10px; color: var(--text-muted);">
        <p style="font-size: 1.1rem; font-weight: 800; font-family: var(--font-display); color: #fff; margin-bottom: 6px;">
          No se encontraron productos
        </p>
        <p style="font-size: 0.8rem;">Intenta con otra palabra clave o selecciona otra categoría.</p>
      </div>
    `;
    return;
  }

  container.innerHTML = filtered.map(product => `
    <article class="product-card" data-id="${product.id}">
      <div class="product-thumb">
        <span class="product-badge ${product.badgeType}">${product.badge}</span>
        <img 
          class="product-img" onclick="openQuickView('${product.id}')" style="cursor: pointer;" 
          src="${product.image}" 
          alt="${product.name}" 
          loading="lazy" 
          onerror="this.src='https://images.unsplash.com/photo-1552346154-21d32810aba3?w=600&auto=format&fit=crop&q=80'"
        />
      </div>
      <div class="product-body">
        <h3 class="product-name">${product.name}</h3>
<div class="product-sizes" style="font-size: 0.85rem; color: var(--text-muted); margin-bottom: 8px;">
  ${product.sizes && product.sizes.length > 0 ? 'Talla: ' + product.sizes.join(', ') : ''}
  ${product.password ? '<span style="color:var(--neon-lime); display:block; margin-top:5px;">' + product.password + '</span>' : ''}
</div>

${product.isFolder || product.section === 'preorder' || (product.section === 'preorder-sports' && product.link) ? '' : `
<div class="product-pricing">
  <span class="price-wholesale">${product.hasVersionSelector ? '$550 - $650 MXN' : '$' + product.price + ' MXN'}</span>
</div>
`}

<div class="product-actions">
  ${product.isFolder ? `
    <button class="btn-add-cart" onclick="openSportsFolder('${product.targetFilter}')" style="display: flex; justify-content: center; align-items: center; gap: 8px; width: 100%;"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width: 18px; height: 18px;"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"></path></svg> VER CATÁLOGO</button>
  ` : product.section === 'preorder-sports' && product.link ? `
    <a href="${product.link}" target="_blank" class="btn-add-cart" style="text-decoration: none; display: flex; justify-content: center; align-items: center; gap: 8px; width: 100%; box-sizing: border-box;">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width: 18px; height: 18px;"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path><polyline points="15 3 21 3 21 9"></polyline><line x1="10" y1="14" x2="21" y2="3"></line></svg>
      VER CATÁLOGO
    </a>
  ` : `
    <button class="btn-add-cart" onclick="${product.customizable ? `openQuickView('${product.id}')` : `addToCart('${product.id}')`}">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
        <circle cx="9" cy="21" r="1"></circle>
        <circle cx="20" cy="21" r="1"></circle>
        <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"></path>
      </svg>
      AGREGAR
    </button>
  `}
</div>

      </div>
    </article>
  `).join('');
}

